/// Catalogue of the synthesised sound effects shipped in `assets/sfx/`
/// (generated by `tools/sfx/`, described in `assets/sfx/MANIFEST.md` and,
/// for the Sprint 2 groups, `assets/sfx/MANIFEST.<group>.md`).
///
/// Every sound the app can play is a [SoundCue]: a value of [Sfx] (the 83
/// "core" sounds of Sprint 1) or a [GameSfx] constant declared by a game /
/// the Rendez-vous meta in its own folder (`<jeu>_sounds.dart`, listed in
/// `kSfxGroups`, `lib/features/sound_catalog.dart`). Code never builds an
/// asset path by hand, and a unit test checks that each cue's file exists,
/// that its duration matches and that every group stays within its quota
/// (`tools/sfx/quotas.json`).
library;

import 'dart:math' as math;

import 'package:flutter/foundation.dart' show immutable;

/// How loud / how important a sound is, for the anti-fatigue governor.
enum SfxTier {
  /// Interface clicks, micro-blips (very frequent, quiet).
  ui,

  /// Regular game sounds (cards, chips, actions).
  game,

  /// Short fanfares (small/medium win, dealer bust, power...).
  fanfare,

  /// Big fanfares (big win, blackjack, streak of 5, rank up, welcome bonus).
  jackpot,
}

/// One playable sound (core [Sfx] value or a game's [GameSfx]).
abstract interface class SoundCue {
  /// Base name of the WAV file in `assets/sfx/` (without extension).
  String get file;
  int get durationMs;
  SfxTier get tier;

  /// Seamless loop: play it on a loop channel, never as a one-shot.
  bool get loop;

  /// Minimum interval between two plays of this sound (or of its variant
  /// group), enforced by the governor.
  int get cooldownMs;

  /// Path relative to the Flutter asset root.
  String get assetPath;

  /// Path relative to `assets/` (what audioplayers' AssetSource expects).
  String get audioplayersPath;
  Duration get duration;

  /// Sounds that count as the same voice for rate limiting (`card_deal_3` →
  /// `card_deal`).
  String get group;

  /// Short name for logs and test output.
  String get label;
}

final _variant = RegExp(r'^(.*)_\d$');
String _variantGroup(String file) {
  final m = _variant.firstMatch(file);
  return m == null ? file : m.group(1)!;
}

/// A sound of a Sprint 2 group (`tools/sfx/games/<group>.mjs`): declare it as
/// a `static const` in the group's `<jeu>_sounds.dart`, e.g.
/// `static const ballTick = GameSfx('roulette_ball_tick', 160, tier: SfxTier.ui);`
/// ([file] must start with `<group>_`, [durationMs] must match the WAV).
@immutable
final class GameSfx implements SoundCue {
  const GameSfx(this.file, this.durationMs, {this.tier = SfxTier.game, this.loop = false, this.cooldownMs = 35});

  @override
  final String file;
  @override
  final int durationMs;
  @override
  final SfxTier tier;
  @override
  final bool loop;
  @override
  final int cooldownMs;

  @override
  String get assetPath => 'assets/sfx/$file.wav';
  @override
  String get audioplayersPath => 'sfx/$file.wav';
  @override
  Duration get duration => Duration(milliseconds: durationMs);
  @override
  String get group => _variantGroup(file);
  @override
  String get label => file;

  @override
  bool operator ==(Object other) => other is GameSfx && other.file == file;
  @override
  int get hashCode => file.hashCode;
  @override
  String toString() => 'GameSfx($file)';
}

