/// Random variants, so repeated sounds never sound mechanical.
abstract final class SfxVariants {
  static const cardDeal = [Sfx.cardDeal1, Sfx.cardDeal2, Sfx.cardDeal3, Sfx.cardDeal4];
  static const cardFlip = [Sfx.cardFlip1, Sfx.cardFlip2];
  static const chipClink = [Sfx.chipClink1, Sfx.chipClink2, Sfx.chipClink3, Sfx.chipClink4];

  static Sfx pick(List<Sfx> variants, math.Random random) => variants[random.nextInt(variants.length)];
}

